use super::*;use std::collections::BTreeMap;use std::time::Duration;
#[test]fn se1_r8_lineage_hides_stale_and_queued_unused_slots_without_losing_originals(){
 let store=Arc::new(Store::default());let writer=Arc::new(Mutex::new(()));let lineage=Arc::new(Lineage::default());let worker=Worker::coherent(store.clone(),writer.clone(),lineage.clone());let p=preview();let first=lineage.snapshot().unwrap();worker.stage_at(p.clone(),Some(first)).unwrap();let a=done(&worker);let old=load(&*store,&a.scope,a.world).unwrap().unwrap();let proof=old.future_secret();
 assert!(lineage.block("attach begins"));assert!(worker.view().1.is_none());assert!(worker.begin_fresh(a.world).is_err());assert!(worker.stage_at(p.clone(),Some(first)).is_err());assert!(load(&*store,&a.scope,a.world).unwrap().unwrap().future_secret().as_str()==proof.as_str());
 assert!(lineage.update("enrolled".into(),true));let mut fresh=p.clone();fresh.base["baseFingerprint"]=serde_json::json!("b".repeat(64));fresh.sample.sequence+=1;fresh.sample.started=Instant::now();fresh.until=fresh.sample.started+Duration::from_secs(30);
 let held=writer.lock().unwrap();worker.stage_at(fresh.clone(),lineage.snapshot()).unwrap();assert!(lineage.block("recovery starts while staging"));drop(held);let end=Instant::now()+Duration::from_secs(3);while worker.view().0{assert!(Instant::now()<end);std::thread::yield_now();}assert!(worker.view().1.is_none());assert!(lineage.update("recovered".into(),true));fresh.base["baseFingerprint"]=serde_json::json!("c".repeat(64));fresh.sample.sequence+=1;fresh.sample.started=Instant::now();fresh.until=fresh.sample.started+Duration::from_secs(30);worker.stage_at(fresh,lineage.snapshot()).unwrap();let b=done(&worker);assert_ne!(a.world,b.world);worker.begin_fresh(b.world).unwrap();assert!(!lineage.block("late enrollment"));assert_eq!(worker.view().1.unwrap().world,b.world);assert!(load(&*store,&a.scope,a.world).unwrap().is_some());
}
#[test]fn se1_r8_native_offer_and_identity_transition_choose_one_order_and_keep_offered_original(){
 for _ in 0..32{let store=Arc::new(Store::default());let lineage=Arc::new(Lineage::default());let worker=Arc::new(Worker::coherent(store.clone(),Arc::new(Mutex::new(())),lineage.clone()));worker.stage(preview()).unwrap();let a=done(&worker);let barrier=Arc::new(std::sync::Barrier::new(3));let w=worker.clone();let b=barrier.clone();let offer=std::thread::spawn(move||{b.wait();w.begin_fresh(a.world).is_ok()});let g=lineage.clone();let b=barrier.clone();let transition=std::thread::spawn(move||{b.wait();g.block("ownership changes")});barrier.wait();let offered=offer.join().unwrap();let changed=transition.join().unwrap();assert_ne!(offered,changed);assert_eq!(worker.fresh_started(),offered);assert_eq!(worker.view().1.is_some(),offered);if offered{worker.claim(a.world,nt2_local_ws::owner::Id::OsProcess(7),100).unwrap();let claimed=done(&worker);assert_eq!(claimed.world,a.world);assert_eq!(claimed.phase,Phase::Claimed);assert!(!lineage.block("retry cannot rebase a claimed original"));let record=load(&*store,&claimed.scope,claimed.world).unwrap().unwrap();let bytes=original(&record,false);worker.seal_activation(claimed.world,bytes.clone(),record.scope().desktop.clone()).unwrap();assert_eq!(done(&worker).phase,Phase::ActivationSubmitted);assert!(!lineage.block("uncertain activation remains the same original"));assert!(load(&*store,&claimed.scope,claimed.world).unwrap().unwrap().activation_original().unwrap().as_slice()==bytes.as_slice());}}
}
#[derive(Default)]struct Store{data:Mutex<BTreeMap<String,Vec<u8>>>,fail:Mutex<Option<usize>>}
impl CredentialStore for Store{
 fn save(&self,p:&crate::secrets::ServiceProfile,b:&crate::secrets::SecretBlob)->Result<(),crate::secrets::StoreError>{let mut fail=self.fail.lock().unwrap();if let Some(left)=fail.as_mut(){if *left==0{return Err(crate::secrets::StoreError::Unavailable)}*left-=1;}self.data.lock().unwrap().insert(format!("{p:?}"),b.bytes().to_vec());Ok(())}
 fn load(&self,p:&crate::secrets::ServiceProfile)->Result<Option<crate::secrets::SecretBlob>,crate::secrets::StoreError>{self.data.lock().unwrap().get(&format!("{p:?}")).map(|b|crate::secrets::SecretBlob::new(b.clone())).transpose()}
 fn delete(&self,p:&crate::secrets::ServiceProfile)->Result<(),crate::secrets::StoreError>{self.data.lock().unwrap().remove(&format!("{p:?}"));Ok(())}
}
fn preview()->Preview{
 let config=serde_json::json!({"seed":424242,"seedPolicy":"shared-fixed","randomizeLoot":true});let uuid=||uuid::Uuid::new_v4().to_string();
 let scope=Scope{origin:"https://provisional.invalid".into(),service:"service".into(),service_epoch:uuid(),account:uuid(),device:uuid::Uuid::new_v4(),desktop:uuid(),desktop_epoch:uuid(),room:uuid(),run:uuid(),run_epoch:uuid(),config:1,config_digest:crate::protocol_connection::canonical_fingerprint(&serde_json::to_vec(&config).unwrap()).unwrap(),preparation:String::new()};
 let entry=w::EntryScope{service_id:Some(scope.service.clone()),service_epoch:Some(scope.service_epoch.clone()),account_id:Some(scope.account.clone()),device_id:Some(scope.device.to_string()),room_id:Some(scope.room.clone()),run_id:Some(scope.run.clone()),run_epoch:Some(scope.run_epoch.clone()),config_revision:Some(1),config_digest:Some(scope.config_digest.clone()),base_preparation_id:Some(uuid()),base_fingerprint:Some("a".repeat(64)),seed_policy:Some("shared-fixed".into()),randomize_loot:Some(true),actual_seed:Some("424242".into())};
 let started=Instant::now();Preview{scope,configuration:config,base:serde_json::to_value(entry).unwrap(),seed:424242,policy:5,until:started+Duration::from_secs(30),sample:crate::connection_time::Stamp{sequence:1,started}}
}
fn done(worker:&Worker)->View{let deadline=Instant::now()+Duration::from_secs(3);loop{let(busy,view,error)=worker.view();if !busy{assert!(error.is_none(),"{error:?}");return view.unwrap()}assert!(Instant::now()<deadline);std::thread::sleep(Duration::from_millis(1));}}
fn original(record:&Record,cancel:bool)->Vec<u8>{
 let mut request=w::Request{major:Some(1),revision:Some(protocol::REVISION.into()),service_id:Some(record.scope.service.clone()),service_epoch:Some(record.scope.service_epoch.clone()),session_epoch:Some(record.scope.desktop_epoch.clone()),request_id:Some(uuid::Uuid::new_v4().to_string()),..Default::default()};
 if cancel{request.entry_cancel=Some(w::EntryCancel{scope:Some(record.entry_scope().unwrap()),identity:Some(record.entry_identity()),recovery_proof:Some(record.secret.clone()),world_offline:Some(true)})}
 else{request.entry_activate=Some(w::EntryActivate{scope:Some(record.entry_scope().unwrap()),identity:Some(record.entry_identity()),recovery_proof:Some(record.secret.clone()),game_version:Some("fixture".into()),mod_version:Some("fixture".into()),bridge_version:Some("fixture".into()),capabilities:Some(vec![]),observation:Some(w::GameObservation{game_instance_id:Some(record.instance.to_string()),world_token:Some(record.world.simple().to_string()),observation_revision:Some(1),actual_seed:Some(record.seed.to_string()),loaded:Some(true),protected:Some(true),inventory_complete:Some(true),..Default::default()})})}
 protocol::validate("Request",&request).unwrap();serde_json::to_vec(&request).unwrap()
}
fn activated(record:&Record)->w::Response{
 let s=record.entry_scope().unwrap();let original=record.activation.as_ref().unwrap();
 let intent=w::PendingIntent{pending_id:Some(record.pending.to_string()),preparation_id:Some(record.scope.preparation.clone()),service_id:s.service_id.clone(),service_epoch:s.service_epoch.clone(),room_id:s.room_id.clone(),run_id:s.run_id.clone(),run_epoch:s.run_epoch.clone(),config_revision:s.config_revision,config_digest:s.config_digest.clone(),account_id:s.account_id.clone(),device_id:s.device_id.clone(),original_desktop_id:Some(record.scope.desktop.clone()),original_desktop_epoch:Some(record.scope.desktop_epoch.clone()),world_token:Some(record.world.simple().to_string()),context_id:Some(record.context.simple().to_string()),seed_policy:s.seed_policy.clone(),randomize_loot:s.randomize_loot,actual_seed:s.actual_seed.clone()};
 w::Response{major:Some(1),revision:Some(protocol::REVISION.into()),service_id:Some(record.scope.service.clone()),service_epoch:original.meta.original_service_epoch.clone(),request_id:original.meta.request_id.clone(),entry:Some(w::EntryState{scope:Some(s),identity:Some(record.entry_identity()),state:Some("activated".into()),reason:Some("activated".into()),may_play:Some(false),..Default::default()}),pending:Some(w::PendingState{intent:Some(intent),generation:Some(2),state:Some("pending".into()),reason:Some("current".into()),may_play:Some(false),sample:Some(w::ConnectionSample{origin_request_id:original.meta.request_id.clone(),channel:Some("pending-http".into()),credential_id:Some("fixture".into()),sample_key:Some("a".repeat(64))}),preparation_remaining_ms:Some(60000),review_remaining_ms:Some(60000),preparation_state:Some("consumed".into()),bound_actual_seed:Some(record.seed.to_string()),..Default::default()}),..Default::default()}
}
fn waiting_receipt(record:&Record,state:&str)->w::Response{
 let mut r=activated(record);let p=r.pending.as_mut().unwrap();let i=serde_json::to_value(p.intent.as_ref().unwrap()).unwrap();let id=uuid::Uuid::new_v4().to_string();let attachment=uuid::Uuid::new_v4().to_string();
 p.state=Some("promoted".into());p.waiting_id=Some(id.clone());
 r.waiting=Some(serde_json::from_value(serde_json::json!({"intent":{"waitingId":id,"pendingReservationId":i["pendingId"],"serviceId":i["serviceId"],"accountId":i["accountId"],"deviceId":i["deviceId"],"preparationId":i["preparationId"],"preparationServiceEpoch":i["serviceEpoch"],"originalDesktopId":i["originalDesktopId"],"originalDesktopEpoch":i["originalDesktopEpoch"],"roomId":i["roomId"],"runId":i["runId"],"runEpoch":i["runEpoch"],"configRevision":i["configRevision"],"configDigest":i["configDigest"],"worldToken":i["worldToken"],"contextId":i["contextId"],"actualSeed":i["actualSeed"],"seedPolicy":i["seedPolicy"],"randomizeLoot":i["randomizeLoot"],"originalAttachmentId":attachment,"originalAttachRequestId":record.activation.as_ref().unwrap().meta.request_id,"originalAttachFingerprint":record.activation.as_ref().unwrap().fingerprint,"originalGameInstanceId":record.instance.to_string(),"originalObservationRevision":1,"contentDigest":"b".repeat(64)},"generation":1,"state":state,"reason":if state=="recoverable"{"owner_disconnected"}else{"awaiting_host_start"},"mayPlay":false,"ownerRemainingMs":if state=="recoverable"{0}else{30000},"reviewRemainingMs":60000,"currentContextId":i["contextId"],"owner":{"familyId":uuid::Uuid::new_v4().to_string(),"desktopId":i["originalDesktopId"],"desktopSessionEpoch":i["originalDesktopEpoch"],"gameSessionId":uuid::Uuid::new_v4().to_string(),"gameSessionEpoch":uuid::Uuid::new_v4().to_string(),"attachmentId":attachment,"gameInstanceId":record.instance.to_string()},"sample":{"originRequestId":r.request_id,"channel":"waiting-http","credentialId":"fixture","sampleKey":"c".repeat(64)},"currentReport":{"revision":1,"contentDigest":"b".repeat(64),"capturedAt":"2026-10-17T00:00:00Z","complete":true,"loaded":true,"protected":true,"contentValid":true}})).unwrap());r
}
#[test]fn se1_r6_real_waiting_and_recoverable_receipts_preserve_pending_proof_and_original(){
 for state in ["waiting","recoverable"]{let p=preview();let store=Store::default();stage(&store,&p).unwrap();let mut head=read_head(&store,&p.scope).unwrap().unwrap();head.record.claim(nt2_local_ws::owner::Id::OsProcess(7),100).unwrap();let actor=head.record.scope.desktop.clone();head.record.original(original(&head.record,false),false,&actor).unwrap();let before=head.record.activation_original().unwrap();let secret=head.record.future_secret();
  let response=waiting_receipt(&head.record,state);protocol::validate("Response",&response).unwrap();assert_eq!(response.waiting.as_ref().unwrap().may_play,Some(false));assert!(response.waiting_proof.is_none()&&response.credentials.is_none()&&response.canonical_admission.is_none());head.record.confirm_activation(&response,"424242").unwrap();save_head(&store,&head).unwrap();let cold=load(&store,&p.scope,head.record.world).unwrap().unwrap();let c=cold.canonical().unwrap();let marker=crate::startup_local::promote_provisional(&store,&cold).unwrap();assert_eq!(marker.kind,"nt2-waiting");assert!(c.waiting.is_some()&&c.waiting_proof.is_none());assert!(cold.activation_original().unwrap()==before);assert!(cold.future_secret().as_str()==secret.as_str());assert!(crate::startup_pending::load(&store,&c.scope,cold.world).unwrap().is_none());assert_eq!(c.scope.desktop,actor);
 }
}
#[test]fn se1_r6_recoverable_receipt_refuses_changed_lineage_correlation_proof_and_terminal(){
 let p=preview();let store=Store::default();stage(&store,&p).unwrap();let mut head=read_head(&store,&p.scope).unwrap().unwrap();head.record.claim(nt2_local_ws::owner::Id::OsProcess(7),100).unwrap();let actor=head.record.scope.desktop.clone();head.record.original(original(&head.record,false),false,&actor).unwrap();let good=waiting_receipt(&head.record,"recoverable");
 for field in ["waitingId","pendingReservationId","serviceId","accountId","deviceId","preparationId","preparationServiceEpoch","originalDesktopId","originalDesktopEpoch","roomId","runId","runEpoch","configRevision","configDigest","worldToken","contextId","actualSeed","seedPolicy","randomizeLoot"]{let mut value=serde_json::to_value(&good).unwrap();value["waiting"]["intent"][field]=match field{"configRevision"=>serde_json::json!(2),"randomizeLoot"=>serde_json::json!(false),"actualSeed"=>serde_json::json!("424243"),"seedPolicy"=>serde_json::json!("shared-random"),"configDigest"=>serde_json::json!("d".repeat(64)),_=>serde_json::json!(uuid::Uuid::new_v4().to_string())};let wrong:w::Response=serde_json::from_value(value).unwrap();let mut copy=head.record.clone();assert!(copy.confirm_activation(&wrong,"424242").and_then(|_|copy.validate()).is_err(),"accepted changed {field}");assert!(head.record.canonical().is_none());}
 for fault in ["terminal","mayPlay","request","pendingProof"]{let mut wrong=good.clone();match fault{"terminal"=>wrong.waiting.as_mut().unwrap().state=Some("terminal".into()),"mayPlay"=>wrong.waiting.as_mut().unwrap().may_play=Some(true),"request"=>wrong.request_id=Some(uuid::Uuid::new_v4().to_string()),"pendingProof"=>wrong.pending_proof=Some("x".repeat(43)),_=>unreachable!()};assert!(head.record.confirm_activation(&wrong,"424242").is_err(),"accepted {fault}");}
 head.record.confirm_activation(&good,"424242").unwrap();save_head(&store,&head).unwrap();
 for field in ["originalAttachmentId","originalAttachRequestId","originalAttachFingerprint","originalGameInstanceId","originalObservationRevision","contentDigest"]{let mut value=serde_json::to_value(&good).unwrap();value["waiting"]["intent"][field]=match field{"originalObservationRevision"=>serde_json::json!(2),"originalAttachFingerprint"|"contentDigest"=>serde_json::json!("d".repeat(64)),_=>serde_json::json!(uuid::Uuid::new_v4().to_string())};let wrong:w::Response=serde_json::from_value(value).unwrap();assert!(head.record.confirm_activation(&wrong,"424242").is_err(),"rebound previously confirmed {field}");}
}
#[test]fn se1_provisional_real_pending_promotion_preserves_original_without_fake_reserve(){
 let p=preview();let store=Store::default();stage(&store,&p).unwrap();let mut head=read_head(&store,&p.scope).unwrap().unwrap();head.record.claim(nt2_local_ws::owner::Id::OsProcess(7),100).unwrap();let actor=head.record.scope.desktop.clone();head.record.original(original(&head.record,false),false,&actor).unwrap();
 assert!(crate::startup_local::promote_provisional(&store,&head.record).is_err());let response=activated(&head.record);
 for fault in ["request","pending","terminal"]{let mut wrong=response.clone();match fault{"request"=>wrong.request_id=Some(uuid::Uuid::new_v4().to_string()),"pending"=>wrong.pending.as_mut().unwrap().intent.as_mut().unwrap().pending_id=Some(uuid::Uuid::new_v4().to_string()),"terminal"=>wrong.pending.as_mut().unwrap().state=Some("terminal".into()),_=>unreachable!()}assert!(head.record.confirm_activation(&wrong,"424242").is_err());}
 head.record.confirm_activation(&response,"424242").unwrap();save_head(&store,&head).unwrap();let cold=load(&store,&p.scope,head.record.world).unwrap().unwrap();let receipt=cold.canonical().unwrap();assert_eq!(receipt.pending_generation,2);assert_eq!(receipt.pending.pending_id,Some(cold.pending.to_string()));assert!(receipt.waiting.is_none());
 let marker=crate::startup_local::promote_provisional(&store,&cold).unwrap();let recalled=crate::startup_local::recall(&store,&cold.scope.origin,&cold.scope.service,&cold.scope.account,cold.scope.device,&marker).unwrap().unwrap();assert_eq!(recalled.original,receipt.scope);assert!(recalled.original_attach.is_none());assert!(crate::startup_pending::load(&store,&receipt.scope,cold.world).unwrap().is_none());
 let mut corrupt=cold.clone();corrupt.canonical.as_mut().unwrap().pending.pending_id=Some(uuid::Uuid::new_v4().to_string());assert!(corrupt.validate().is_err());assert_eq!(cold.activation_original().unwrap().as_slice(),head.record.activation_original().unwrap().as_slice());
}
#[test]fn se1_provisional_is_honest_distinct_and_secret_stays_out_of_bundle(){
 let p=preview();let store=Store::default();let record=stage(&store,&p).unwrap();let cold=load(&store,&p.scope,record.world).unwrap().unwrap();
 assert_eq!(cold.world,record.world);assert_eq!(cold.secret,record.secret);assert_eq!(cold.context,record.context);assert_eq!(cold.phase,Phase::Staged);
 let bytes=String::from_utf8(record.snapshot().unwrap()).unwrap();assert!(!bytes.contains(&record.secret));assert!(!bytes.contains("pendingProof")&&!bytes.contains("PendingIntent")&&!bytes.contains("mayPlay"));assert!(bytes.contains("nt2-provisional-entry-v1"));
 assert_ne!(record.world,record.context);assert_ne!(record.scope.preparation,p.base["basePreparationId"].as_str().unwrap());assert_eq!(record.secret.len(),43);assert_eq!(record.commitment,format!("{:x}",Sha256::digest(record.secret.as_bytes())));
 let mut head=read_head(&store,&p.scope).unwrap().unwrap();head.record.claim(nt2_local_ws::owner::Id::OsProcess(7),100).unwrap();save_head(&store,&head).unwrap();let mut different=p.clone();different.base["baseFingerprint"]=Value::String("b".repeat(64));assert!(stage(&store,&different).is_err());assert_eq!(load(&store,&p.scope,record.world).unwrap().unwrap().world,record.world);
 let mut auth=p.clone();auth.scope.desktop=uuid::Uuid::new_v4().to_string();auth.scope.desktop_epoch=uuid::Uuid::new_v4().to_string();assert_eq!(stage(&store,&auth).unwrap().world,record.world);
}
